import math
phi_f=0.0
phase='rev'
fwd_start=None
last_print=-10
best_prev=0.0
last_touch=0

def clamp(x,a,b):
    return max(a,min(b,x))

def control(obs):
    global phi_f,phase,fwd_start,last_print,best_prev,last_touch
    h=obs['hitch_deg']
    rig=obs['rig']
    hx,hy=rig['hitch']; rx,ry=rig['trailer_rear']
    b=math.atan2(ry-hy,rx-hx)
    t=obs['t']
    tc=obs['counters']['touches']
    if tc>last_touch:
        last_touch=tc
        wake('touch at t=%.1f h=%.1f phi=%.1f'%(t,h,phi_f))
    if phase=='fwd':
        if abs(h)<6 or (t-fwd_start)>3.5:
            phase='rev'
        else:
            return (0.0,1.0,-23)
    if abs(h)>38:
        phase='fwd'; fwd_start=t
        return (0.0,1.0,-23)
    cam=obs.get('views',{}).get('camera')
    near=9.0
    if cam and cam.get('walls'):
        ox,oy=cam['origin']
        pts=[]
        for bd,d in cam['walls']:
            a=math.radians(bd)
            pts.append((ox+d*math.cos(a)-rx,oy+d*math.sin(a)-ry))
        best=None;bs=-1e9
        for pd in range(-60,61,5):
            c=b+math.radians(pd)
            cc,sc=math.cos(c),math.sin(c)
            free=9.0
            for dx,dy in pts:
                al=dx*cc+dy*sc
                la=-dx*sc+dy*cc
                if al>0 and abs(la)<1.0 and al<free:
                    free=al
            s=min(free,8.0)-0.02*abs(pd)-0.01*abs(pd-best_prev)
            if s>bs:
                bs=s;best=pd
        best_prev=best
        cb,sb=math.cos(b),math.sin(b)
        dpos=None;dneg=None
        for dx,dy in pts:
            al=dx*cb+dy*sb
            la=-dx*sb+dy*cb
            if al<near: near=max(al,0) if abs(la)<1.0 else near
            if -1<=al<=4:
                if la>0: dpos=la if dpos is None else min(dpos,la)
                else: dneg=-la if dneg is None else min(dneg,-la)
        bias=0.0
        if dpos is not None and dneg is not None and dpos+dneg<5:
            bias=math.degrees(math.atan2((dpos-dneg)/2.0,4.0))
        elif dpos is not None and dpos<1.4:
            bias=-math.degrees(math.atan2(1.4-dpos,3.0))
        elif dneg is not None and dneg<1.4:
            bias=math.degrees(math.atan2(1.4-dneg,3.0))
        goal=best+bias
        phi_f=0.7*phi_f+0.3*goal
        if t-last_print>2:
            last_print=t
            print('t%.1f h%.1f best%d bias%.1f phi%.1f dpos%s dneg%s'%(t,h,best,bias,phi_f,dpos,dneg))
    hdes=clamp(-0.6*phi_f,-25,25)
    steer=clamp(2.5*(h-hdes),-34,34)
    sp=-1.0 if near>2 else -0.7
    return (steer,sp,-23)

