import math
L=2.5;A=1.3;B=3.6
pose=[0.0,0.0,0.0]
mem={}
gaze=170
cnt=0
phase='rev'
alpha_f=0.0
lastp=-9

def wrap(a):
    return (a+180.0)%360.0-180.0

def clamp(x,a,b):
    return a if x<a else (b if x>b else x)

def control(obs):
    global gaze,cnt,phase,alpha_f,lastp
    t=obs['t']; dt=obs.get('dt',0.1) or 0.1
    v=obs['motion']['v_mps']; st=math.radians(obs['steer_deg'])
    pose[0]+=v*math.cos(pose[2])*dt; pose[1]+=v*math.sin(pose[2])*dt
    pose[2]+=v*math.tan(st)/L*dt
    X,Y,TH=pose; c=math.cos(TH); s=math.sin(TH)
    psi=obs['hitch_deg']; pr=math.radians(psi)
    rig=obs['rig']; hx,hy=rig['hitch']; rx,ry=rig['trailer_rear']
    ln=math.hypot(rx-hx,ry-hy) or 5.0
    f=B/ln; ax=hx+(rx-hx)*f; ay=hy+(ry-hy)*f
    for nm,vw in (obs.get('views') or {}).items():
        try:
            ox,oy=vw['origin']
            for b,d in vw.get('walls',[]):
                br=math.radians(b); px=ox+d*math.cos(br); py=oy+d*math.sin(br)
                wx=X+px*c-py*s; wy=Y+px*s+py*c
                mem[(round(wx/0.2),round(wy/0.2))]=(wx,wy,t)
        except Exception:
            pass
    for k in [k for k,p in mem.items() if t-p[2]>25]:
        del mem[k]
    cp=math.cos(pr); sp=math.sin(pr)
    pts=[]
    for wx,wy,tt in mem.values():
        dx0=wx-X; dy0=wy-Y
        px=dx0*c+dy0*s; py=-dx0*s+dy0*c
        dx=px-ax; dy=py-ay
        al=-dx*cp+dy*sp; la=dx*sp+dy*cp
        if -3<al<20: pts.append((al,la))
    CAP=12.0; HW=1.5
    res=[]
    for ad in range(-45,46,3):
        ar=math.radians(ad); ca=math.cos(ar); sa=math.sin(ar)
        fr=CAP
        for al,la in pts:
            sd=al*ca+la*sa
            if sd<1.0 or sd>=fr: continue
            if abs(-al*sa+la*ca)<HW: fr=sd
        res.append((ad,fr))
    maxf=max(r[1] for r in res)
    best=None; run=[]; runs=[]
    for ad,fr in res:
        if fr>=maxf-0.6: run.append(ad)
        else:
            if run: runs.append(run)
            run=[]
    if run: runs.append(run)
    runs.sort(key=lambda r:(-len(r),abs(sum(r)/len(r))))
    alpha=sum(runs[0])/len(runs[0])
    alpha_f+=0.3*(alpha-alpha_f)
    D=clamp(maxf,3.0,8.0)
    kappa=2*math.sin(math.radians(alpha_f))/D
    lmin=9; rmax=-9
    for al,la in pts:
        if -2.0<al<2.5:
            if la>0 and la<lmin: lmin=la
            if la<0 and la>rmax: rmax=la
    if lmin<1.7: kappa-=0.08*(1.7-lmin)
    if rmax>-1.7: kappa+=0.08*(1.7+rmax)
    tg=obs.get('target') or {}
    tdist=None
    if tg.get('in_sight') and tg.get('dist_m') is not None:
        b=math.radians(tg['bearing_deg']); d=tg['dist_m']
        tx=0.75+d*math.cos(b); ty=d*math.sin(b)
        dx=tx-ax; dy=ty-ay
        al=-dx*cp+dy*sp; la=dx*sp+dy*cp
        tdist=math.hypot(al,la)
        if 0.3<al<12:
            Dt=max(al,4.0)
            kt=2*la/(Dt*Dt+la*la)
            w=1.0 if al<8 else 0.5
            kappa=w*kt+(1-w)*kappa
    psid=clamp(math.degrees((B+A)*kappa),-30,30)
    status=obs.get('status')
    if phase=='rev' and (abs(psi)>50 or status=='JACKKNIFED'):
        phase='fwd'
    if phase=='fwd':
        if abs(psi)<12: phase='rev'
        else:
            return (clamp(-1.0*psi,-35,35),1.0,gaze)
    ff=math.degrees(math.atan(L*math.sin(pr)/(B+A*math.cos(pr))))
    delta=clamp(ff+1.5*(psi-psid),-45,45)
    spd=-1.0
    if tdist is not None and tdist<7: spd=-0.6
    if abs(psi-psid)>20: spd=-0.6
    brg=wrap(180-psi-alpha_f)
    if gaze>0 and -165<brg<-60: cnt+=1
    elif gaze<0 and 60<brg<165: cnt+=1
    else: cnt=0
    if cnt>15:
        gaze=-gaze; cnt=0
    if t-lastp>2:
        lastp=t
        print('t%.1f psi%.1f psid%.1f a%.0f maxf%.1f L%.1f R%.1f td%s g%d n%d'%(t,psi,psid,alpha_f,maxf,lmin,rmax,tdist,gaze,len(pts)))
    return (delta,spd,gaze)

