import math
L=2.5;A=1.3;B=3.6
pose=[0.0,0.0,0.0]
mem={}
phase='unpin';fwd_d=0.0;ust=None
GZ=[(170,2.5),(64,1.2),(-64,1.2),(-170,2.5),(-64,1.2),(64,1.2)]
gi=0;gt=None
lastp=-9;last_status='PINNED'
K=[i*0.04 for i in range(-8,9)]
cnt=0;kap=0.0;maxf=7.5

def clamp(x,a,b):
    return a if x<a else (b if x>b else x)

def k2psi(k):
    if abs(k)<1e-4: return 0.0
    R=1.0/abs(k); rv=math.sqrt(max(R*R+B*B-A*A,0.01))
    p=math.atan(B/R)+math.atan(A/rv)
    return math.copysign(math.degrees(p),k)

def control(obs):
    global phase,fwd_d,ust,gi,gt,lastp,last_status,cnt,kap,maxf
    t=obs['t']; dt=obs.get('dt') or 0.1
    if gt is None: gt=t
    v=obs['motion']['v_mps']; st=math.radians(obs['steer_deg'])
    pose[0]+=v*math.cos(pose[2])*dt; pose[1]+=v*math.sin(pose[2])*dt
    pose[2]+=v*math.tan(st)/L*dt
    X,Y,TH=pose; c=math.cos(TH); s=math.sin(TH)
    psi=obs['hitch_deg']
    rig=obs['rig']; hx,hy=rig['hitch']; rx,ry=rig['trailer_rear']
    ln=math.hypot(rx-hx,ry-hy) or 5.0
    ux=(rx-hx)/ln; uy=(ry-hy)/ln
    ax=hx+ux*B; ay=hy+uy*B
    for nm,vw in (obs.get('views') or {}).items():
        try:
            ox,oy=vw['origin']
            for b,d in vw.get('walls',[]):
                br=math.radians(b); px=ox+d*math.cos(br); py=oy+d*math.sin(br)
                wx=X+px*c-py*s; wy=Y+px*s+py*c
                mem[(round(wx/0.2),round(wy/0.2))]=(wx,wy,t)
        except Exception:
            pass
    if cnt%50==0:
        for k in [k for k,p in mem.items() if t-p[2]>90]:
            del mem[k]
    pts=[]
    for wx,wy,tt in mem.values():
        dx0=wx-X; dy0=wy-Y
        px=dx0*c+dy0*s; py=-dx0*s+dy0*c
        dx=px-ax; dy=py-ay
        al=dx*ux+dy*uy; la=dx*uy-dy*ux
        if -4.5<al<10 and abs(la)<7: pts.append((al,la))
    lmin=9.0; rmin=9.0
    for al,la in pts:
        if -3.4<al<2.0 and abs(la)<2.2:
            if la>0: lmin=min(lmin,la-1.2)
            else: rmin=min(rmin,-la-1.2)
    status=obs.get('status')
    if status=='PINNED' and last_status!='PINNED':
        phase='unpin'; fwd_d=0.0; ust=None
    last_status=status
    if t-gt>GZ[gi][1]:
        gi=(gi+1)%len(GZ); gt=t
    gaze=GZ[gi][0]
    cnt+=1
    if phase=='unpin':
        if ust is None:
            ust=-15.0 if rmin<lmin else 15.0
        if v>0: fwd_d+=v*dt
        if fwd_d>=1.2: phase='rev'
        else: return (ust,0.8,gaze)
    if phase=='rev' and (abs(psi)>46 or status=='JACKKNIFED'):
        phase='fwd'
    if phase=='fwd':
        if abs(psi)<20: phase='rev'
        else: return (0.0,1.0,gaze)
    if cnt%3==0:
        near=pts
        res=[]
        for k in K:
            free=7.5; sd=0.5
            while sd<=7.01:
                th=k*sd
                if abs(k)<1e-4: px=sd; py=0.0
                else: px=math.sin(th)/k; py=(1-math.cos(th))/k
                ct=math.cos(th); stt=math.sin(th)
                hit=False
                for al,la in near:
                    dx=al-px; dy=la-py
                    a=dx*ct+dy*stt
                    if a<-3.3 or a>1.7: continue
                    l=-dx*stt+dy*ct
                    if -1.45<l<1.45:
                        hit=True; break
                if hit:
                    free=sd-0.5; break
                sd+=0.5
            res.append((k,free))
        maxf=max(r[1] for r in res)
        if maxf<0.6:
            kap=0.2 if rmin<lmin else -0.2
        else:
            runs=[];run=[]
            for k,f in res:
                if f>=maxf-0.25: run.append(k)
                else:
                    if run: runs.append(run)
                    run=[]
            if run: runs.append(run)
            runs.sort(key=lambda r:(-len(r),abs(sum(r)/len(r)-kap)))
            kap=sum(runs[0])/len(runs[0])
    kk=kap
    tg=obs.get('target') or {}
    tal=None
    if tg.get('in_sight') and tg.get('dist_m') is not None:
        b=math.radians(tg['bearing_deg']); d=tg['dist_m']
        tx=0.75+d*math.cos(b); ty=d*math.sin(b)
        dx=tx-ax; dy=ty-ay
        tal=dx*ux+dy*uy; tla=dx*uy-dy*ux
        if 0.3<tal<9:
            kt=clamp(2*tla/(tal*tal+tla*tla+0.5),-0.3,0.3)
            w=clamp((9-tal)/4.0,0,1)
            kk=w*kt+(1-w)*kap
    psid=clamp(k2psi(kk),-38,38)
    if tal is not None and tal<3: psid*=max(tal,0)/3.0
    pr=math.radians(psi)
    ff=math.degrees(math.atan(L*math.sin(pr)/(B+A*math.cos(pr))))
    delta=clamp(ff+1.5*(psi-psid),-45,45)
    spd=-0.7
    if abs(psi-psid)>12 or maxf<2 or min(lmin,rmin)<0.3: spd=-0.45
    if tal is not None and tal<4: spd=-0.5
    if t-lastp>2:
        lastp=t
        print('t%.1f %s psi%.1f psid%.1f k%.2f mf%.1f l%.1f r%.1f tal%s n%d'%(t,phase,psi,psid,kap,maxf,lmin,rmin,None if tal is None else round(tal,1),len(pts)))
    return (delta,spd,gaze)

