    if status=='PINNED' and last_status!='PINNED':
        phase='unpin'; fwd_d=0.0; ust=None
    last_status=status
    if t-gt>GZ[gi][1]:
        gi=(gi+1)%len(GZ); gt=t
    gaze=GZ[gi][0]
    cnt+=1
    if phase=='unpin':
        if ust is None:
            ust=-15.0 if rmin<lmin else 15.0
        if v>0: fwd_d+=v*dt
        if fwd_d>=1.2: phase='rev'
        else: return (ust,0.8,gaze)
    if phase=='rev' and (abs(psi)>46 or status=='JACKKNIFED'):
        phase='fwd'
    if phase=='fwd':
        if abs(psi)<20: phase='rev'
        else: return (0.0,1.0,gaze)
    if cnt%3==0:
        near=pts
        res=[]
        for k in K:
            free=7.5; sd=0.5
            while sd<=7.01:
                th=k*sd
                if abs(k)<1e-4: px=sd; py=0.0
                else: px=math.sin(th)/k; py=(1-math.cos(th))/k
                ct=math.cos(th); stt=math.sin(th)
                hit=False
                for al,la in near:
                    dx=al-px; dy=la-py
                    a=dx*ct+dy*stt
                    if a<-3.3 or a>1.7: continue
                    l=-dx*stt+dy*ct
                    if -1.45<l<1.45:
                        hit=True; break
                if hit:
                    free=sd-0.5; break
                sd+=0.5
            res.append((k,free))
