        if maxf<0.6:
            kap=0.2 if rmin<lmin else -0.2
        else:
            runs=[];run=[]
            for k,f in res:
                if f>=maxf-0.25: run.append(k)
                else:
                    if run: runs.append(run)
                    run=[]
            if run: runs.append(run)
            runs.sort(key=lambda r:(-len(r),abs(sum(r)/len(r)-kap)))
            kap=sum(runs[0])/len(runs[0])
    kk=kap
    tg=obs.get('target') or {}
    tal=None
    if tg.get('in_sight') and tg.get('dist_m') is not None:
        b=math.radians(tg['bearing_deg']); d=tg['dist_m']
        tx=0.75+d*math.cos(b); ty=d*math.sin(b)
        dx=tx-ax; dy=ty-ay
        tal=dx*ux+dy*uy; tla=dx*uy-dy*ux
        if 0.3<tal<9:
            kt=clamp(2*tla/(tal*tal+tla*tla+0.5),-0.3,0.3)
            w=clamp((9-tal)/4.0,0,1)
            kk=w*kt+(1-w)*kap
