    pr=math.radians(psi)
    ff=math.degrees(math.atan(L*math.sin(pr)/(B+A*math.cos(pr))))
    delta=clamp(ff+1.5*(psi-psid),-45,45)
    spd=-0.7
    if abs(psi-psid)>12 or maxf<2 or min(lmin,rmin)<0.3: spd=-0.45
    if tal is not None and tal<4: spd=-0.5
    if t-lastp>2:
        lastp=t
        print('t%.1f %s psi%.1f psid%.1f k%.2f mf%.1f l%.1f r%.1f tal%s n%d'%(t,phase,psi,psid,kap,maxf,lmin,rmin,None if tal is None else round(tal,1),len(pts)))
    return (delta,spd,gaze)

