import math
L=2.5;A=1.3;B=3.6
pose=[0.0,0.0,0.0]
mem={}
S={'ph':'rev','fd':0.0,'ls':'PINNED','gi':0,'gt':None,'lp':-9.0,'n':0,'psid':0.0}
GZ=[(165,1.6),(-150,1.4)]

def clamp(x,a,b): return a if x<a else (b if x>b else x)

def k2psi(k):
    if abs(k)<1e-4: return 0.0
    R=1.0/abs(k); rv=math.sqrt(max(R*R+B*B-A*A,0.01))
    p=math.atan(B/R)+math.atan(A/rv)
    return math.copysign(math.degrees(p),k)

def control(obs):
    t=obs['t'];dt=obs.get('dt') or 0.1
    if S['gt'] is None: S['gt']=t
    v=obs['motion']['v_mps'];sd=math.radians(obs['steer_deg'])
    pose[0]+=v*math.cos(pose[2])*dt;pose[1]+=v*math.sin(pose[2])*dt
    pose[2]+=v*math.tan(sd)/L*dt
    X,Y,TH=pose;c=math.cos(TH);s=math.sin(TH)
    psi=obs['hitch_deg'];pr=math.radians(psi)
    rig=obs['rig'];hx,hy=rig['hitch'];rx,ry=rig['trailer_rear']
    ln=math.hypot(rx-hx,ry-hy) or 5.0
    ux=(rx-hx)/ln;uy=(ry-hy)/ln
    ax=hx+ux*B;ay=hy+uy*B
    for nm,vw in (obs.get('views') or {}).items():
        try:
            ox,oy=vw['origin']
            for b,d in vw.get('walls',[]):
                br=math.radians(b);px=ox+d*math.cos(br);py=oy+d*math.sin(br)
                wx=X+px*c-py*s;wy=Y+px*s+py*c
                mem[(round(wx/0.2),round(wy/0.2))]=(wx,wy)
        except Exception: pass
    S['n']+=1
    if S['n']%50==0:
        for k in [k for k,p in mem.items() if abs(p[0]-X)>25 or abs(p[1]-Y)>25]: del mem[k]
    pts=[]
    for wx,wy in mem.values():
        dx0=wx-X;dy0=wy-Y
        px=dx0*c+dy0*s;py=-dx0*s+dy0*c
        dx=px-ax;dy=py-ay
        al=dx*ux+dy*uy;la=dx*uy-dy*ux
        if -4<al<9 and abs(la)<8: pts.append((al,la))
    status=obs.get('status')
    if status=='PINNED' and S['ls']!='PINNED' and S['ph']=='rev':
        S['ph']='unpin';S['fd']=0.0
    S['ls']=status
    if t-S['gt']>GZ[S['gi']][1]:
        S['gi']=(S['gi']+1)%len(GZ);S['gt']=t
    gaze=GZ[S['gi']][0]
    if S['ph']=='unpin':
        if v>0: S['fd']+=v*dt
        if S['fd']>=1.5: S['ph']='rev'
        else: return (0.0,0.8,gaze)
    if S['ph']=='rev' and (abs(psi)>52 or status=='JACKKNIFED'):
        S['ph']='fwd'
    if S['ph']=='fwd':
        if abs(psi)<20: S['ph']='rev'
        else: return (0.0,1.0,gaze)
    side=[p for p in pts if -3.7<p[0]<1.6]
    L0=[la for a,la in side if la>0.3];R0=[la for a,la in side if la<-0.3]
    lw=min(L0) if L0 else None;rw=max(R0) if R0 else None
    lc=(lw-1.2) if lw is not None else 9.0;rc=(-rw-1.2) if rw is not None else 9.0
    lws={};rws={}
    for st in range(2,8):
        band=[la for a,la in pts if st-0.6<a<st+0.6]
        if lw is not None:
            cd=[la for la in band if lw-0.8<la<lw+2.5]
            if cd: lw=min(cd)
        lim=(lw-2.6) if lw is not None else 0.0
        cr=[la for la in band if la<lim and (rw is None or la>rw-2.5)]
        if cr: rw=max(cr)
        lws[st]=lw;rws[st]=rw
    l5=lws[5];r5=rws[5]
    if l5 is not None and r5 is not None:
        if l5-r5<4.8: lat=(l5+r5)/2
        else: lat=max(l5-2.4,r5+2.0)
    elif l5 is not None: lat=l5-2.4
    elif r5 is not None: lat=r5+2.4
    else: lat=0.0
    rmin=9.0;lmin=9.0
    for st in (2,3,4):
        if rws[st] is not None: rmin=min(rmin,-rws[st]-1.2)
        if lws[st] is not None: lmin=min(lmin,lws[st]-1.2)
    if rmin<0.6: lat+=2.0*(0.6-rmin)
    if lmin<0.6: lat-=2.0*(0.6-lmin)
    D=5.0
    kap=2*lat/(D*D+lat*lat)
    psid=clamp(k2psi(kap),-32,32)
    if rc<0.4: psid=max(psid,psi+12*(0.4-rc)/0.4)
    if lc<0.4: psid=min(psid,psi-12*(0.4-lc)/0.4)
    tg=obs.get('target') or {}
    tal=None
    if tg.get('in_sight') and tg.get('dist_m') is not None:
        b=math.radians(tg['bearing_deg']);d=tg['dist_m']
        tx=0.75+d*math.cos(b);ty=d*math.sin(b)
        dx=tx-ax;dy=ty-ay
        tal=dx*ux+dy*uy;tla=dx*uy-dy*ux
        if 0.3<tal<10 and min(rc,lc,rmin,lmin)>0.4:
            Dt=max(tal,3.5)
            kt=2*tla/(Dt*Dt+tla*tla)
            pt=clamp(k2psi(kt),-28,28)
            if tal<3: pt*=max(tal,0)/3.0
            w=clamp((10-tal)/5.0,0,1)
            psid=w*pt+(1-w)*psid
    psid=clamp(psid,-36,36)
    S['psid']=psid
    ff=math.degrees(math.atan(L*math.sin(pr)/(B+A*math.cos(pr))))
    delta=clamp(ff+1.6*(psi-psid),-45,45)
    spd=-0.55
    if min(rc,lc,rmin,lmin)<0.45 or abs(psi-psid)>15: spd=-0.35
    if tal is not None and tal<4: spd=-0.4
