import math
st={'b':0.5,'W':3.2,'c':None,'mode':'pre','fd':0.0,'tp':-10}

def clamp(v,a,b):
    return max(a,min(b,v))

def fit(pts):
    if len(pts)<2:
        return None
    a=None;b=None
    for it in range(3):
        n=len(pts)
        mx=sum(p[0] for p in pts)/n; my=sum(p[1] for p in pts)/n
        sxx=sum((p[0]-mx)**2 for p in pts)
        if sxx<0.3:
            return (my,None,mx)
        sxy=sum((p[0]-mx)*(p[1]-my) for p in pts)
        b=sxy/sxx; a=my-b*mx
        p2=[p for p in pts if abs(p[1]-(a+b*p[0]))<0.3]
        if len(p2)<2 or len(p2)==len(pts):
            break
        pts=p2
    return (a,b,None)

def control(obs):
    h=obs.get('hitch_deg',0.0) or 0.0
    rig=obs['rig']
    xr,yr=rig['trailer_rear']
