                bb=math.radians(bd[0]); d=bd[1]
                x=ox+d*math.cos(bb); y=oy+d*math.sin(bb)
                if -6.0<x<0.8 and 0.5<abs(y)<4.0:
                    (L if y>0 else R).append((x,y))
        except Exception:
            pass
    fl=fit(L); fr=fit(R)
    slopes=[f[1] for f in (fl,fr) if f and f[1] is not None]
    if slopes:
