import math
phase='rev'
hd=0.0
fa=0.0
n=0
lastc=12.0

def wrap(a):
    while a>180: a-=360
    while a<-180: a+=360
    return a

def cl(x,a,b):
    return max(a,min(b,x))

def getpts(obs):
    out=[]
    vs=obs.get('views') or {}
    for k,v in vs.items():
        if not v: continue
        try:
            ox,oy=v['origin']
            for b,d in (v.get('walls') or []):
                r=math.radians(b); out.append((ox+d*math.cos(r),oy+d*math.sin(r)))
        except Exception:
            pass
    return out

def control(obs):
    global phase,hd,fa,n,lastc
    n+=1
    h=obs['hitch_deg']; rig=obs['rig']
    if phase=='rev' and abs(h)>50:
        phase='fwd'
        try: wake('hitch %.0f, pulling forward' % h)
        except Exception: pass
    if phase=='fwd':
        if abs(h)<10:
            phase='rev'
        else:
            return (0.0, 1.5, -41)
    R=rig['trailer_rear']; B=math.radians(rig['trailer_heading_deg']+180.0)
    cb,sb=math.cos(B),math.sin(B)
    P=[]
    for (px,py) in getpts(obs):
        dx=px-R[0]; dy=py-R[1]
        P.append((dx*cb+dy*sb, dx*sb-dy*cb))
    at=None
    tg=obs.get('target') or {}
    if tg.get('in_sight') and tg.get('bearing_deg') is not None and tg.get('dist_m') is not None:
        e=rig['eye']; r=math.radians(tg['bearing_deg'])
        tx=e[0]+tg['dist_m']*math.cos(r); ty=e[1]+tg['dist_m']*math.sin(r)
        dx=tx-R[0]; dy=ty-R[1]
        al=dx*cb+dy*sb; lt=dx*sb-dy*cb
        if al>0.5: at=math.degrees(math.atan2(lt,al))
    if P:
        L=12.0
        cands=list(range(-60,61,3))
        cs=[]
        for a in cands:
            ra=math.radians(a); c,s=math.cos(ra),math.sin(ra)
            clr=L
            for (x,y) in P:
                ss=x*c+y*s; lat=-x*s+y*c
                if 0.3<ss<clr and abs(lat)<1.7: clr=ss
            cs.append(clr)
        m=max(cs); lastc=m
        ok=[c>=m-0.3 for c in cs]
        runs=[]; i=0
        while i<len(cands):
            if ok[i]:
                j=i
                while j+1<len(cands) and ok[j+1]: j+=1
                runs.append((i,j)); i=j+1
            else: i+=1
        best=None
        if at is not None:
            for (i,j) in runs:
                if cands[i]-3<=at<=cands[j]+3: best=(i,j)
        if best is None:
            best=max(runs,key=lambda r:(r[1]-r[0], -abs(cands[r[0]]+cands[r[1]])))
        i,j=best
        a=(cands[i]+cands[j])/2.0
        if at is not None and cands[i]-3<=at<=cands[j]+3:
            a=0.5*a+0.5*at
        fa=0.7*fa+0.3*a
        hd=cl(0.8*fa,-35,35)
    ff=-math.degrees(math.atan(0.4*math.sin(math.radians(hd))))
    st=cl(ff+2.5*(h-hd),-42,42)
    sp=-1.2 if lastc>4 else -0.7
    if n%30==0:
        print('t%.0f h%.1f hd%.1f fa%.1f clr%.1f at%s np%d' % (obs['t'],h,hd,fa,lastc,at,len(P)))
    return (st, sp, -41)

